import{_ as a,o as i,c as o,a5 as r}from"./chunks/framework.BwlBv862.js";const m=JSON.parse('{"title":"Requisitos","description":"","frontmatter":{"title":"Requisitos","docId":"user.start.requirements","translationKey":"user.start.requirements","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"c68c149552a943cf0f03393c5dac91bd62abf9c50f791d7b0757599754f4804e","translationRevision":"1664c2a41360e5483b50977d7e29bcce1c4d590447196b2a0cf0c394ab9f2ef8","order":10},"headers":[],"relativePath":"es/user/requirements.md","filePath":"es/user/requirements.md","lastUpdated":1794611623000}'),n={name:"es/user/requirements.md"};function t(s,e,l,c,d,u){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="requirements" tabindex="-1">Requisitos <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requisitos {#requirements}&quot;">​</a></h1><h2 id="goal" tabindex="-1">Objetivo <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Objetivo {#goal}&quot;">​</a></h2><p>Elegir un paquete de escritorio compatible e identificar los servicios necesarios antes de instalar.</p><h2 id="what-you-need" tabindex="-1">Qué necesitas <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;Qué necesitas {#what-you-need}&quot;">​</a></h2><ul><li>Un equipo Windows x86_64 o Linux x86_64 para los paquetes de escritorio publicados. El workflow actual compila esos dos destinos. No publica escritorio para macOS ni un APK de Android.</li><li>Una sesión gráfica funcional. Windows necesita el runtime WebView2 de Microsoft. Linux necesita un entorno GTK/WebKitGTK compatible; el DEB declara sus paquetes de ejecución y el AppImage incluye los auxiliares multimedia revisados.</li><li>Acceso de red a TikTok para una conexión LIVE real. Una sala sin transmisión, una sesión de invitado caducada o un límite del servicio no se corrigen cambiando una automatización.</li><li>Espacio fuera de la instalación para SQLite, plugins y registros. La aplicación utiliza un directorio de datos por usuario; mover el ejecutable no mueve esos datos.</li></ul><p>La cuenta Cloud es necesaria para operaciones de catálogo o colaboración basadas en cuenta, no para todos los editores locales. OBS sólo es necesario para mostrar widgets en una transmisión. Las integraciones de audio/TTS pueden requerir un plugin separado y su propio proveedor o servicio.</p><h2 id="check-the-environment" tabindex="-1">Comprueba el entorno <a class="header-anchor" href="#check-the-environment" aria-label="Permalink to &quot;Comprueba el entorno {#check-the-environment}&quot;">​</a></h2><ol><li>Elige el paquete de tu sistema operativo y arquitectura x86_64.</li><li>En Windows, instala WebView2 si el instalador indica que falta. En Linux, resuelve bibliotecas de ejecución ausentes con el gestor de paquetes de tu distribución.</li><li>Comprueba que la ventana abre antes de conectar con TikTok o añadir plugins.</li><li>Continúa con la <a href="./installation.html">instalación</a> y el <a href="./first-live.html">primer LIVE</a>.</li></ol><h2 id="expected-result" tabindex="-1">Resultado esperado <a class="header-anchor" href="#expected-result" aria-label="Permalink to &quot;Resultado esperado {#expected-result}&quot;">​</a></h2><p>La aplicación abre y su navegación principal funciona sin conexión. Las integraciones opcionales pueden permanecer deshabilitadas hasta que exista su plugin o capacidad del host.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Ante una ventana vacía o un cierre temprano, recopila los diagnósticos de inicio y la versión exacta del paquete. AppImage y DEB son formatos distintos de instalación; ninguno se ejecuta en Android. Consulta el <a href="./termux.html">alcance de Termux y del modo sin interfaz</a>. La compilación desde código tiene requisitos adicionales en Desarrollo.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p>Si no aparece la ventana, busca el log nativo <code>tiktools.log</code> (<code>controller.log</code> en modo controlador): Windows <code>%LOCALAPPDATA%/TikTools/logs</code>, Linux <code>${XDG_DATA_HOME:-~/.local/share}/TikTools/logs</code>, salvo cambios de <code>TIKTOOLS_HOME</code> o <code>TIKTOOLS_LOG_DIR</code>. El registro puede fallar antes de crear archivo. Conserva el error de terminal disponible y revisa <a href="./preferences/troubleshooting.html#operational-details">retención y privacidad</a> antes de compartir.</p>',14)])])}const h=a(n,[["render",t]]);export{m as __pageData,h as default};
